SELECT set_config('request.jwt.claim.role','service_role',false);
SELECT set_config('request.jwt.claim.sub','f49d6153-1835-4455-81f3-2918d5d3484e',false);
BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'What is ''loom efficiency %'' typically calculated as?', '["The ratio of actual production output (or running time) to the theoretical maximum possible over the same period, expressed as a percentage","The exact number of colors used in a woven pattern","The percentage of synthetic fiber used in the warp yarn","The total width of fabric measured in centimeters"]'::jsonb, 'The ratio of actual production output (or running time) to the theoretical maximum possible over the same period, expressed as a percentage', 'Loom efficiency % compares actual achieved production (picks woven, or running time) against the theoretical maximum the loom could produce running continuously at its rated speed — stoppages from breaks, changeovers, and maintenance all reduce this efficiency figure.', 1, '{"loom-efficiency"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Why does a higher warp/weft breakage rate directly reduce loom efficiency, beyond just the time lost fixing each individual break?', '["Each stoppage requires the loom to decelerate, stop, be repaired, and then re-accelerate, all of which consumes time the loom isn''t producing fabric — and frequent small stoppages accumulate significantly over a shift","Breakage rate has no relationship to loom efficiency at all","Higher breakage rates always increase loom efficiency by keeping operators more alert","Efficiency is calculated independently of any stoppage frequency or duration"]'::jsonb, 'Each stoppage requires the loom to decelerate, stop, be repaired, and then re-accelerate, all of which consumes time the loom isn''t producing fabric — and frequent small stoppages accumulate significantly over a shift', 'Beyond the direct repair time for each break, the stop-repair-restart cycle (deceleration, operator response time, fixing, re-threading if needed, re-acceleration) all represent non-productive time; since this overhead repeats with every single break, a high breakage rate compounds into a significant cumulative efficiency loss over a full shift.', 2, '{"loom-efficiency","breakage-rate"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'What is a ''weaver''s beam'' capacity typically measured in, and why does beam capacity matter for production planning?', '["Total warp length wound on the beam; larger capacity means fewer beam changes are needed during a production run, reducing associated downtime","Beam capacity is measured only in the beam''s physical weight, unrelated to warp length or production planning","Beam capacity has no relationship to how often the loom needs to stop for beam changes","Beam capacity refers only to the number of colors that can be loaded onto one beam"]'::jsonb, 'Total warp length wound on the beam; larger capacity means fewer beam changes are needed during a production run, reducing associated downtime', 'A weaver''s beam holds a finite total length of warp yarn; a larger-capacity beam allows more fabric to be woven before a beam change (and the associated tying-in/downtime) is needed, directly affecting how much productive, uninterrupted running time is achievable in production planning.', 2, '{"beam-capacity"}'::text[]);
COMMIT;
